python3 -c "
import socket, struct, fcntl
s=socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
for ifc in ['eth0','eth1']:
    try:
        ip=fcntl.ioctl(s.fileno(), 0x8915, struct.pack('256s', ifc[:15].encode()))
        print(ifc, socket.inet_ntoa(ip[20:24]))
    except Exception as e:
        print(ifc, 'no addr', e)
"

